            vals.midRailType = (vals.fenceStyle === 'executive_custom') ? ((vals.midRailType && vals.midRailType !== 'none') ? vals.midRailType : 'hss_rect') : 'none';


            vals.midRailSize = (vals.midRailSize && vals.midRailSize !== 'NONE' && vals.midRailSize !== 'none') ? vals.midRailSize : 'HSS1.5x1.5x14GA';


            vals.picketType = (vals.picketType && vals.picketType !== 'none') ? vals.picketType : 'hss_rect';


