            const noPosts = (vals.postType === 'none' || vals.postHeight === 0);


            vals.postSpacing = noPosts ? 0 : ((vals.postSpacing && vals.postSpacing > 0) ? vals.postSpacing : 48);


            vals.leftPost = noPosts ? 'no' : 'yes';


            vals.rightPost = noPosts ? 'no' : 'yes';


