    function loadDpartsTemplate(templateName) {
        if (!dpartsState.templates[templateName]) return;
        dpartsState.activeTemplate = templateName;
        const tmpl = dpartsState.templates[templateName];
        dpartsState.currentItems = tmpl.items.map(item => ({ ...item }));
        renderDpartsUI();
    }

    function renderDpartsUI() {
        const gateSelect = document.getElementById('sel-dparts-gate-type');
        const descEl = document.getElementById('dparts-template-desc');
        const badgeEl = document.getElementById('dparts-job-badge');
        const countBadge = document.getElementById('dparts-items-count-badge');
        const tableBody = document.getElementById('dparts-table-body');

        const jobNo = document.getElementById('inp-jobNo')?.value?.trim() || document.getElementById('exp-jobNo')?.value?.trim() || 'J-303';
        const fabNo = document.getElementById('inp-fabNo')?.value?.trim() || document.getElementById('exp-fabNo')?.value?.trim() || 'F-202';
        if (badgeEl) badgeEl.textContent = `Job: ${jobNo} | Fab: ${fabNo}`;

        // Populate / Update Gate Dropdown Selector
        if (gateSelect) {
            const tmplKeys = Object.keys(dpartsState.templates);
            const currentOptions = Array.from(gateSelect.options).map(o => o.value);
            const isMatch = tmplKeys.length === currentOptions.length && tmplKeys.every(k => currentOptions.includes(k));
            if (!isMatch) {
                gateSelect.innerHTML = '';
                tmplKeys.forEach(tKey => {
                    const opt = document.createElement('option');
                    opt.value = tKey;
                    const tmplTitle = (dpartsState.templates[tKey] && dpartsState.templates[tKey].title) || tKey;
                    opt.textContent = `${tKey} — ${tmplTitle.trim()}`;
                    gateSelect.appendChild(opt);
                });
            }
            gateSelect.value = dpartsState.activeTemplate;
        }

        // Update description
        if (descEl && dpartsState.templates[dpartsState.activeTemplate]) {
            descEl.textContent = dpartsState.templates[dpartsState.activeTemplate].title || dpartsState.activeTemplate;
        }

        // Render Table Body
        if (tableBody) {
            tableBody.innerHTML = '';
            if (dpartsState.currentItems.length === 0) {
                const tr = document.createElement('tr');
                tr.innerHTML = `<td colspan="7" style="padding: 24px; text-align: center; color: #8b949e;">No hardware items configured. Click "Add Custom Item" or search parts below.</td>`;
                tableBody.appendChild(tr);
            } else {
                const escapeAttr = (str) => {
                    if (str === null || str === undefined) return '';
                    return String(str)
                        .replace(/&/g, '&amp;')
                        .replace(/"/g, '&quot;')
                        .replace(/'/g, '&#39;')
                        .replace(/</g, '&lt;')
                        .replace(/>/g, '&gt;');
                };

                dpartsState.currentItems.forEach((item, idx) => {
                    const tr = document.createElement('tr');
                    tr.style.cssText = `border-bottom: 1px solid #21262d; background: ${item.selected !== false ? 'rgba(255,255,255,0.02)' : 'rgba(0,0,0,0.3)'}; ${item.selected === false ? 'opacity: 0.5;' : ''}`;

                    tr.innerHTML = `
                        <td style="padding: 8px 10px; text-align: center;">
                            <input type="checkbox" class="dparts-row-chk" data-idx="${idx}" ${item.selected !== false ? 'checked' : ''} style="cursor: pointer; width: 14px; height: 14px;" />
                        </td>
                        <td style="padding: 8px 10px;">
                            <input type="number" min="1" step="1" class="dparts-row-qty" data-idx="${idx}" value="${item.qty || 1}" style="width: 60px; padding: 4px 6px; font-size: 12px; background: #161b22; border: 1px solid #30363d; border-radius: 4px; color: #ffffff; text-align: center;" />
                        </td>
                        <td style="padding: 8px 10px;">
                            <input type="text" class="dparts-row-part" data-idx="${idx}" value="${escapeAttr(item.partNo)}" placeholder="Optional" style="width: 100%; padding: 4px 6px; font-size: 12px; background: #161b22; border: 1px solid #30363d; border-radius: 4px; color: #ffffff;" />
                        </td>
                        <td style="padding: 8px 10px;">
                            <input type="text" class="dparts-row-desc" data-idx="${idx}" value="${escapeAttr(item.description)}" placeholder="Part Description" style="width: 100%; padding: 4px 6px; font-size: 12px; font-weight: 500; background: #161b22; border: 1px solid #30363d; border-radius: 4px; color: #ffffff;" />
                        </td>
                        <td style="padding: 8px 10px;">
                            <select class="dparts-row-finish" data-idx="${idx}" style="width: 100%; padding: 4px 6px; font-size: 12px; background: #161b22; border: 1px solid #30363d; border-radius: 4px; color: #ffffff;">
                                <option value="No Paint" ${item.finish === 'No Paint' ? 'selected' : ''}>No Paint</option>
                                <option value="Primer" ${item.finish === 'Primer' ? 'selected' : ''}>Primer</option>
                                <option value="Raw" ${item.finish === 'Raw' ? 'selected' : ''}>Raw</option>
                                <option value="Raw SS" ${item.finish === 'Raw SS' ? 'selected' : ''}>Raw SS</option>
                                <option value="Zinc" ${item.finish === 'Zinc' ? 'selected' : ''}>Zinc</option>
                                <option value="Powder Coat" ${item.finish === 'Powder Coat' ? 'selected' : ''}>Powder Coat</option>
                                <option value="Galvanized" ${item.finish === 'Galvanized' ? 'selected' : ''}>Galvanized</option>
                                <option value="None" ${item.finish === 'None' ? 'selected' : ''}>None</option>
                            </select>
                        </td>
                        <td style="padding: 8px 10px;">
                            <input type="text" class="dparts-row-inst" data-idx="${idx}" value="${escapeAttr(item.instructions)}" placeholder="Special instructions / notes..." style="width: 100%; padding: 4px 6px; font-size: 12px; background: #161b22; border: 1px solid #30363d; border-radius: 4px; color: #8b949e;" />
                        </td>
                        <td style="padding: 8px 10px; text-align: center;">
                            <button type="button" class="btn-dparts-del-row" data-idx="${idx}" style="background: none; border: none; color: #ff5555; cursor: pointer; padding: 4px; border-radius: 4px;" title="Remove row">
                                <i data-lucide="trash-2" style="width: 14px; height: 14px;"></i>
                            </button>
                        </td>
                    `;
                    tableBody.appendChild(tr);
                });
            }
        }

        // Bind Table Row Listeners
        tableBody?.querySelectorAll('.dparts-row-chk').forEach(chk => {
            chk.addEventListener('change', (e) => {
                const idx = parseInt(e.target.dataset.idx);
                if (dpartsState.currentItems[idx]) {
                    dpartsState.currentItems[idx].selected = e.target.checked;
                    renderDpartsUI();
                }
            });
        });

        tableBody?.querySelectorAll('.dparts-row-qty').forEach(input => {
            input.addEventListener('change', (e) => {
                const idx = parseInt(e.target.dataset.idx);
                if (dpartsState.currentItems[idx]) {
                    dpartsState.currentItems[idx].qty = parseFloat(e.target.value) || 1;
                }
            });
        });

        tableBody?.querySelectorAll('.dparts-row-part').forEach(input => {
            input.addEventListener('input', (e) => {
                const idx = parseInt(e.target.dataset.idx);
                if (dpartsState.currentItems[idx]) {
                    dpartsState.currentItems[idx].partNo = e.target.value;
                }
            });
        });

        tableBody?.querySelectorAll('.dparts-row-desc').forEach(input => {
            input.addEventListener('input', (e) => {
                const idx = parseInt(e.target.dataset.idx);
                if (dpartsState.currentItems[idx]) {
                    dpartsState.currentItems[idx].description = e.target.value;
                }
            });
        });

        tableBody?.querySelectorAll('.dparts-row-finish').forEach(select => {
            select.addEventListener('change', (e) => {
                const idx = parseInt(e.target.dataset.idx);
                if (dpartsState.currentItems[idx]) {
                    dpartsState.currentItems[idx].finish = e.target.value;
                }
            });
        });

        tableBody?.querySelectorAll('.dparts-row-inst').forEach(input => {
            input.addEventListener('input', (e) => {
                const idx = parseInt(e.target.dataset.idx);
                if (dpartsState.currentItems[idx]) {
                    dpartsState.currentItems[idx].instructions = e.target.value;
                }
            });
        });

        tableBody?.querySelectorAll('.btn-dparts-del-row').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const idx = parseInt(btn.closest('button').dataset.idx);
                dpartsState.currentItems.splice(idx, 1);
                renderDpartsUI();
            });
        });

        // Update selected items count badge
        const selectedCount = dpartsState.currentItems.filter(i => i.selected !== false).length;
        if (countBadge) {
            countBadge.textContent = `${selectedCount} item${selectedCount === 1 ? '' : 's'} selected`;
        }

        const dpartsStatusBadge = document.getElementById('badge-dparts-status');
        if (dpartsStatusBadge) {
            dpartsStatusBadge.textContent = `${selectedCount} Part${selectedCount === 1 ? '' : 's'} Configured`;
        }

        if (window.lucide) lucide.createIcons();
    }

    async function applyAllBordersToXlsxBuffer(rawArrayBuf) {
        if (!window.JSZip) return rawArrayBuf;
        try {
            const zip = await JSZip.loadAsync(rawArrayBuf);
            const customStylesXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
  <fonts count="2">
    <font><sz val="11"/><name val="Calibri"/><family val="2"/></font>
    <font><b/><sz val="11"/><name val="Calibri"/><family val="2"/></font>
  </fonts>
  <fills count="2">
    <fill><patternFill patternType="none"/></fill>
    <fill><patternFill patternType="gray125"/></fill>
  </fills>
  <borders count="2">
    <border><left/><right/><top/><bottom/><diagonal/></border>
    <border>
      <left style="thin"><color auto="1"/></left>
      <right style="thin"><color auto="1"/></right>
      <top style="thin"><color auto="1"/></top>
      <bottom style="thin"><color auto="1"/></bottom>
      <diagonal/>
    </border>
  </borders>
  <cellStyleXfs count="1">
    <xf numFmtId="0" fontId="0" fillId="0" borderId="0"/>
  </cellStyleXfs>
  <cellXfs count="3">
    <xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>
    <xf numFmtId="0" fontId="1" fillId="0" borderId="1" xfId="0" applyFont="1" applyBorder="1" applyAlignment="1"><alignment horizontal="left" vertical="center"/></xf>
    <xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1" applyAlignment="1"><alignment horizontal="left" vertical="center"/></xf>
  </cellXfs>
  <cellStyles count="1">
    <cellStyle name="Normal" xfId="0" builtinId="0"/>
  </cellStyles>
</styleSheet>`;

            zip.file("xl/styles.xml", customStylesXml);

            let sheetXml = await zip.file("xl/worksheets/sheet1.xml").async("string");
            // Add style 1 (Header with border + bold) to row 2 cells, style 2 (Data with border) to row 3+ cells
            sheetXml = sheetXml.replace(/<row r="2"[^>]*>([\s\S]*?)<\/row>/, (match, inner) => {
                const styledInner = inner.replace(/<c r="([A-Z]+2)"([^>]*)>/g, (m, ref, rest) => {
                    const cleanRest = rest.replace(/\s+s="[^"]*"/g, '');
                    return `<c r="${ref}" s="1"${cleanRest}>`;
                });
                return `<row r="2">${styledInner}</row>`;
            });

            sheetXml = sheetXml.replace(/<row r="([3-9]|\d{2,})"[^>]*>([\s\S]*?)<\/row>/g, (match, rNum, inner) => {
                const styledInner = inner.replace(/<c r="([A-Z]+\d+)"([^>]*)>/g, (m, ref, rest) => {
                    const cleanRest = rest.replace(/\s+s="[^"]*"/g, '');
                    return `<c r="${ref}" s="2"${cleanRest}>`;
                });
                return `<row r="${rNum}">${styledInner}</row>`;
            });

            zip.file("xl/worksheets/sheet1.xml", sheetXml);
            return await zip.generateAsync({ type: "arraybuffer" });
        } catch (e) {
            console.warn("Could not apply XML borders to XLSX:", e);
            return rawArrayBuf;
        }
    }

    function saveDpartsConfiguration() {
        // Collect latest values from inputs
        const tableBody = document.getElementById('dparts-table-body');
        if (tableBody) {
            tableBody.querySelectorAll('tr').forEach((tr, idx) => {
                if (dpartsState.currentItems[idx]) {
                    const qtyInp = tr.querySelector('.dparts-row-qty');
                    const partInp = tr.querySelector('.dparts-row-part');
                    const descInp = tr.querySelector('.dparts-row-desc');
                    const finishSelect = tr.querySelector('.dparts-row-finish');
                    const instInp = tr.querySelector('.dparts-row-inst');
                    const chkInp = tr.querySelector('.dparts-row-chk');

                    if (qtyInp) dpartsState.currentItems[idx].qty = parseFloat(qtyInp.value) || 1;
                    if (partInp) dpartsState.currentItems[idx].partNo = partInp.value.trim();
                    if (descInp) dpartsState.currentItems[idx].description = descInp.value.trim();
                    if (finishSelect) dpartsState.currentItems[idx].finish = finishSelect.value;
                    if (instInp) dpartsState.currentItems[idx].instructions = instInp.value.trim();
                    if (chkInp) dpartsState.currentItems[idx].selected = chkInp.checked;
                }
            });
        }

        dpartsState.savedTemplate = dpartsState.activeTemplate;
        dpartsState.savedItems = JSON.parse(JSON.stringify(dpartsState.currentItems));
        dpartsState.isSaved = true;

        // Update badge in Advance Features panel
        const selectedCount = dpartsState.savedItems.filter(i => i.selected !== false).length;
        const dpartsStatusBadge = document.getElementById('badge-dparts-status');
        if (dpartsStatusBadge) {
            dpartsStatusBadge.textContent = `Saved: ${dpartsState.savedTemplate} (${selectedCount} parts)`;
            dpartsStatusBadge.style.color = '#38ef7d';
        }

        // Close screen
        const dpartsScreen = document.getElementById('dparts-screen');
        if (dpartsScreen) dpartsScreen.classList.add('hidden');

        // Toast feedback
        const toast = document.createElement('div');
        toast.className = 'ai-success-toast';
        toast.innerHTML = `<i data-lucide="check-circle" style="color:#000; vertical-align:middle; margin-right:4px;"></i> Dparts Saved (${dpartsState.savedTemplate}) — Will be included in ZIP export!`;
        document.body.appendChild(toast);
        if (window.lucide) lucide.createIcons();
        setTimeout(() => {
            toast.style.animation = 'slideUp 0.3s cubic-bezier(0.16, 1, 0.3, 1) reverse';
            setTimeout(() => toast.remove(), 300);
        }, 3500);
    }
    window.saveDpartsConfiguration = saveDpartsConfiguration;

    async function exportDpartsExcel(jobNo, fabNo, returnArrayBuffer = false) {
        if (!window.XLSX) {
            alert("XLSX library not loaded. Please refresh the page.");
            return null;
        }
        const safeJobNo = (jobNo || document.getElementById('inp-jobNo')?.value?.trim() || document.getElementById('exp-jobNo')?.value?.trim() || 'J-303').trim().replace(/[^a-zA-Z0-9_-]/g, '_');
        const safeFabNo = (fabNo || document.getElementById('inp-fabNo')?.value?.trim() || document.getElementById('exp-fabNo')?.value?.trim() || 'F-202').trim().replace(/[^a-zA-Z0-9_-]/g, '_');
        
        const activeTmplKey = (dpartsState.isSaved && dpartsState.savedTemplate) ? dpartsState.savedTemplate : dpartsState.activeTemplate;
        const tmplTitle = (dpartsState.templates[activeTmplKey] && dpartsState.templates[activeTmplKey].title) || activeTmplKey || 'GATES';

        const headers = ["Quantity", "Sage #", "Description", "Finish", "Special order instructions"];
        const rows = [
            ["", tmplTitle, "", "", ""],
            headers
        ];

        const activeItemList = (dpartsState.isSaved && dpartsState.savedItems && dpartsState.savedItems.length > 0) ? dpartsState.savedItems : dpartsState.currentItems;
        const selectedItems = activeItemList.filter(i => i.selected !== false);
        selectedItems.forEach(item => {
            rows.push([
                item.qty || 1,
                item.partNo || '',
                item.description || '',
                item.finish || 'No Paint',
                item.instructions || ''
            ]);
        });

        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.aoa_to_sheet(rows);

        // Column widths
        ws['!cols'] = [
            { wch: 10 }, // Quantity
            { wch: 14 }, // Sage #
            { wch: 45 }, // Description
            { wch: 15 }, // Finish
            { wch: 35 }  // Special order instructions
        ];

        XLSX.utils.book_append_sheet(wb, ws, "DPART GATES");

        const rawBuf = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
        const styledBuf = await applyAllBordersToXlsxBuffer(rawBuf);

        if (returnArrayBuffer) {
            return styledBuf;
        }

        const blob = new Blob([styledBuf], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `DPART-${safeJobNo}-${safeFabNo}.xlsx`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        URL.revokeObjectURL(url);

        const toast = document.createElement('div');
        toast.className = 'ai-success-toast';
        toast.innerHTML = `<i data-lucide="check-circle" style="color:#000; vertical-align:middle; margin-right:4px;"></i> Dparts Excel Downloaded (DPART-${safeJobNo}-${safeFabNo}.xlsx)!`;
        document.body.appendChild(toast);
        if (window.lucide) lucide.createIcons();
        setTimeout(() => {
            toast.style.animation = 'slideUp 0.3s cubic-bezier(0.16, 1, 0.3, 1) reverse';
            setTimeout(() => toast.remove(), 300);
        }, 3500);
    }
    window.exportDpartsExcel = exportDpartsExcel;
    window.dpartsState = dpartsState;
    window.loadDpartsTemplate = loadDpartsTemplate;

    function initDpartsManager() {
        if (window.DPARTS_DB && window.DPARTS_DB.templates) {
            dpartsState.templates = window.DPARTS_DB.templates;
        }
        if (window.DPARTS_DB && window.DPARTS_DB.partsCatalog) {
            dpartsState.partsCatalog = window.DPARTS_DB.partsCatalog;
        }
        loadDpartsTemplate('PED GATE');

        // Nav button click -> open screen
        const btnNavDparts = document.getElementById('btn-nav-dparts');
        const dpartsScreen = document.getElementById('dparts-screen');
        const btnDpartsBack = document.getElementById('btn-dparts-back');

        if (btnNavDparts && dpartsScreen) {
            btnNavDparts.addEventListener('click', () => {
                const advPanel = document.getElementById('advance-features-panel');
                if (advPanel) advPanel.classList.add('hidden');
                dpartsScreen.classList.remove('hidden');
                if (dpartsState.isSaved && dpartsState.savedTemplate) {
                    dpartsState.activeTemplate = dpartsState.savedTemplate;
                    dpartsState.currentItems = JSON.parse(JSON.stringify(dpartsState.savedItems));
                }
                renderDpartsUI();
            });
        }

        if (btnDpartsBack && dpartsScreen) {
            btnDpartsBack.addEventListener('click', () => {
                dpartsScreen.classList.add('hidden');
            });
        }

        // Save Configuration Button
        document.getElementById('btn-dparts-save')?.addEventListener('click', saveDpartsConfiguration);

        // Gate Type Dropdown change
        const gateSelect = document.getElementById('sel-dparts-gate-type');
        if (gateSelect) {
            gateSelect.addEventListener('change', (e) => {
                loadDpartsTemplate(e.target.value);
            });
        }

        // Select / Deselect All
        document.getElementById('btn-dparts-select-all')?.addEventListener('click', () => {
            dpartsState.currentItems.forEach(i => i.selected = true);
            renderDpartsUI();
        });

        document.getElementById('btn-dparts-deselect-all')?.addEventListener('click', () => {
            dpartsState.currentItems.forEach(i => i.selected = false);
            renderDpartsUI();
        });

        // Add Custom Item
        document.getElementById('btn-dparts-add-custom')?.addEventListener('click', () => {
            dpartsState.currentItems.push({
                selected: true,
                qty: 1,
                partNo: '',
                description: 'Custom Hardware Item',
                finish: 'No Paint',
                instructions: ''
            });
            renderDpartsUI();
        });

        // Search Catalog
        const searchInput = document.getElementById('inp-dparts-catalog-search');
        const searchResults = document.getElementById('dparts-search-results');

        if (searchInput && searchResults) {
            searchInput.addEventListener('input', (e) => {
                const q = e.target.value.trim().toLowerCase();
                if (!q || q.length < 2) {
                    searchResults.classList.add('hidden');
                    searchResults.innerHTML = '';
                    return;
                }

                const matches = (dpartsState.partsCatalog || []).filter(p => 
                    (p.description && p.description.toLowerCase().includes(q)) ||
                    (p.partNo && p.partNo.toLowerCase().includes(q)) ||
                    (p.category && p.category.toLowerCase().includes(q))
                ).slice(0, 20);

                if (matches.length === 0) {
                    searchResults.innerHTML = `<div style="padding: 10px 14px; font-size: 12px; color: #8b949e;">No matching parts found for "${e.target.value}".</div>`;
                    searchResults.classList.remove('hidden');
                    return;
                }

                searchResults.innerHTML = '';
                matches.forEach(item => {
                    const div = document.createElement('div');
                    div.style.cssText = `padding: 8px 12px; border-bottom: 1px solid #30363d; cursor: pointer; display: flex; align-items: center; justify-content: space-between; font-size: 12px; transition: background 0.15s;`;
                    div.innerHTML = `
                        <div style="display: flex; flex-direction: column;">
                            <span style="font-weight: 600; color: #ffffff;">${item.description}</span>
                            <span style="font-size: 10.5px; color: #8b949e;">Part #: <span style="color: #00d4ff;">${item.partNo || 'N/A'}</span> | Finish: ${item.finish || 'Raw'} | Category: ${item.category || 'Hardware'}</span>
                        </div>
                        <button type="button" class="btn secondary" style="padding: 2px 8px; font-size: 11px; border-color: #38ef7d; color: #38ef7d;">
                            + Add
                        </button>
                    `;
                    div.addEventListener('mouseenter', () => div.style.background = 'rgba(0,212,255,0.1)');
                    div.addEventListener('mouseleave', () => div.style.background = 'transparent');
                    div.addEventListener('click', () => {
                        dpartsState.currentItems.push({
                            selected: true,
                            qty: 1,
                            partNo: item.partNo || '',
                            description: item.description || '',
                            finish: item.finish || 'No Paint',
                            instructions: ''
                        });
                        searchInput.value = '';
                        searchResults.classList.add('hidden');
                        renderDpartsUI();
                    });
                    searchResults.appendChild(div);
                });
                searchResults.classList.remove('hidden');
            });

            document.addEventListener('click', (e) => {
                if (!searchInput.contains(e.target) && !searchResults.contains(e.target)) {
                    searchResults.classList.add('hidden');
                }
            });
        }

        // Export Dparts Excel Button
        document.getElementById('btn-export-dparts-excel')?.addEventListener('click', () => {
            exportDpartsExcel();
        });
    }
    initDpartsManager();

