                const grade = item.grade || getSteelGrade(item.shape || item.desc, item.remark);


                drawCellText(grade, 243, 11, "center");


                // Surface Finish


                const shortFinish = finishText.toUpperCase();


                drawCellText(shortFinish, 254, 12, "center");


